export class ConfError extends Error {}

const NAME = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const newTable = () => ({ t: 'table', m: new Map(), hdr: false })

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  for (let i = 0; i < lines.length; i++) {
    try {
      cur = doLine(lines[i], root, cur)
    } catch (e) {
      if (e instanceof ConfError) e.message = `line ${i + 1}: ${e.message}`
      throw e
    }
  }
  return root
}

const fail = (m) => { throw new ConfError(m) }

function doLine(s, root, cur) {
  let p = 0
  const skip = () => { while (p < s.length && isWs(s[p])) p++ }
  const atEnd = () => p >= s.length || s[p] === '#' || s[p] === ';'

  function str(q) {
    // s[p] is the opening quote
    p++
    let out = ''
    for (;;) {
      if (p >= s.length) fail('unterminated string')
      const c = s[p]
      if (c === q) { p++; return out }
      if (q === '"' && c === '\\') {
        p++
        if (p >= s.length) fail('unterminated string')
        const e = s[p]
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) { out += map[e]; p++ }
        else if (e === 'u') {
          const h = s.slice(p + 1, p + 5)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          p += 5
        } else fail(`invalid escape \\${String.fromCodePoint(s.codePointAt(p))}`)
      } else { out += c; p++ }
    }
  }

  function name() {
    const c = s[p]
    if (c === '"' || c === "'") return str(c)
    const st = p
    while (p < s.length && NAME.test(s[p])) p++
    if (p === st) fail('expected a name')
    return s.slice(st, p)
  }

  function dotted() {
    const segs = [name()]
    for (;;) {
      const save = p
      skip()
      if (s[p] === '.') { p++; skip(); segs.push(name()) } else { p = save; break }
    }
    return segs
  }

  const INT = '[+-]?\\d+(?:_\\d+)*'
  const intRe = new RegExp(`^${INT}$`)
  const floatRe = new RegExp(`^${INT}(?:\\.\\d+(?:_\\d+)*)?(?:[eE][+-]?\\d+(?:_\\d+)*)?$`)

  function value(prefix) {
    skip()
    if (atEnd() || s[p] === ',' || s[p] === ']' || s[p] === '}') fail('expected a value')
    const c = s[p]
    if (c === '"') return { t: 'string', v: str('"') }
    if (c === "'") return { t: 'string', v: str("'") }
    if (c === '[') return array(prefix)
    if (c === '{') return inline(prefix)
    const st = p
    while (p < s.length && !isWs(s[p]) && !',]}'.includes(s[p]) && s[p] !== ';') p++
    const w = s.slice(st, p)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (intRe.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (floatRe.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    return fail(`invalid value ${w}`)
  }

  function array(prefix) {
    p++
    const arr = { t: 'array', items: [], aot: false }
    for (;;) {
      skip()
      if (atEnd()) fail('unterminated array')
      if (s[p] === ']') { p++; return arr }
      arr.items.push(value(prefix))
      skip()
      if (atEnd()) fail('unterminated array')
      if (s[p] === ',') { p++; continue }
      if (s[p] === ']') { p++; return arr }
      fail('trailing text after a value')
    }
  }

  function inline(prefix) {
    p++
    const tb = newTable()
    skip()
    if (atEnd()) fail('unterminated inline table')
    if (s[p] === '}') { p++; return tb }
    for (;;) {
      skip()
      if (atEnd()) fail('unterminated inline table')
      const segs = dotted()
      skip()
      if (s[p] !== '=') fail('expected = in an inline table')
      p++
      const v = value(prefix.concat(segs))
      assign(tb, prefix, segs, v)
      skip()
      if (atEnd()) fail('unterminated inline table')
      if (s[p] === ',') { p++; continue }
      if (s[p] === '}') { p++; return tb }
      fail('trailing text after a value')
    }
  }

  function walk(tb, prefix, segs) {
    let t = tb
    const path = prefix.slice()
    for (const seg of segs) {
      path.push(seg)
      let ch = t.m.get(seg)
      if (!ch) { ch = newTable(); t.m.set(seg, ch) }
      if (ch.t === 'table') t = ch
      else if (ch.t === 'array' && ch.aot) t = ch.items[ch.items.length - 1]
      else fail(`${path.join('.')} is not a table`)
    }
    return t
  }

  function assign(tb, prefix, segs, v) {
    const t = walk(tb, prefix, segs.slice(0, -1))
    const last = segs[segs.length - 1]
    if (t.m.has(last)) fail(`key ${prefix.concat(segs).join('.')} is defined twice`)
    t.m.set(last, v)
  }

  skip()
  if (p >= s.length || s[p] === '#' || s[p] === ';') return cur

  if (s[p] === '[') {
    p++
    const dbl = s[p] === '['
    if (dbl) p++
    skip()
    const segs = dotted()
    skip()
    if (s[p] !== ']' || (dbl && s[p + 1] !== ']')) fail('unterminated table header')
    p += dbl ? 2 : 1
    skip()
    if (!atEnd()) fail('trailing text after a table header')
    const t = walk(root, [], segs.slice(0, -1))
    const last = segs[segs.length - 1]
    const full = segs.join('.')
    const ex = t.m.get(last)
    if (!dbl) {
      if (!ex) { const n = newTable(); n.hdr = true; t.m.set(last, n); return n }
      if (ex.t !== 'table') fail(`${full} is not a table`)
      if (ex.hdr) fail(`table ${full} is defined twice`)
      ex.hdr = true
      return ex
    }
    if (!ex) {
      const n = newTable()
      t.m.set(last, { t: 'array', items: [n], aot: true })
      return n
    }
    if (ex.t !== 'array' || !ex.aot) fail(`${full} is not an array of tables`)
    const n = newTable()
    ex.items.push(n)
    return n
  }

  const segs = dotted()
  skip()
  if (s[p] !== '=') fail('expected key = value')
  p++
  const v = value([])
  skip()
  if (!atEnd()) fail('trailing text after a value')
  assign(cur, [], segs, v)
  return cur
}
